"""Freeze narration against executed room/tool evidence; preserve original PCM."""
from pathlib import Path
import json
H=Path(__file__).resolve().parent; P=H.parents[1]; R=P.parents[1]
plan=json.loads((H/'revision-plan.json').read_text('utf8'))
changes={
'R01':('이번에는 이 작업실을 실제로 움직이는 작은 게임까지 완성해 보겠습니다. 의자를 누르면 걸어가 앉고, 지도를 펼쳐 경로를 짚고, 책을 꺼내 서서 읽고, 창문에서는 날씨를 바꿉니다. 이제부터 같은 캐릭터와 같은 방을 계속 사용하면서, 각 도구의 입력과 설정이 어떤 결과로 이어지는지 확인하겠습니다.', 'We will take this workshop all the way to a small playable game. Click the chair to walk over and sit, unfold a map to trace a route, take out a book to read while standing, or change the weather at the window. We will keep the same character and room throughout, showing how each tool’s inputs and settings lead to its output.'),
'R25':('이 도구는 실제 설치 과정에서 막힌 부분까지 보여드리겠습니다. 공개된 세 개의 모델 파일은 내려받았지만, 공식 실행 코드가 요구하는 포즈 가이더 파일은 배포 목록에 없었습니다. 다른 구현의 호환 모듈도 확인했지만, 필요한 이미지 인코더의 다운로드 주소가 더 이상 연결되지 않았습니다. 그래서 이번 방에는 이 도구가 생성한 동작을 넣지 않았습니다. 생성에 성공한 결과와 실행에 필요한 파일을 확보하지 못한 상태를 구분해서 확인해야 합니다.', 'Here is where this tool’s actual setup stopped. We downloaded the three published model files, but the PoseGuider checkpoint required by the official inference code was absent from its distribution. We also checked a compatibility implementation, but its required image-encoder download returned an error. Therefore this room contains no animation generated by this tool. A successful generated result must be distinguished from a setup whose required files are still missing.'),
'R30':('오늘 만든 방은 설명란의 링크에서 직접 실행할 수 있습니다. 의자와 지도, 책장과 창문을 눌러 보고, 날씨를 바꿔 같은 리소스가 어떻게 이어지는지 확인해 보세요. 제작 과정에는 사용한 요청문과 설정, 각 도구의 실제 결과도 함께 정리해 두었습니다.', 'You can play the room from the link in the description. Try the chair, map, bookshelf, and window, and change the weather to see how the assets work together. The process notes also contain the prompts, settings, and actual results from each tool.')
}
for s in plan['scenes']:
 if s['id'] in changes:s['ko'],s['en']=changes[s['id']]
 if s['id']=='R25':s.update(title='Sprite-Sheet-Diffusion 실제 설치 점검',blocked=False,evidence='official checkpoint records + companion HTTP404 + upstream missing-PoseGuider issue',screenPlan='실제 확보 3파일→공식 inference.py 필수경로→누락/404 로그; 생성 결과 없음 명시')
 if s['id']=='R30':s['evidence']='https://yamyam-cartographers-room.eazuooz.chatgpt.site'
 if s['id']=='R16':s['screenPlan']='현재 실제 좌판·윤곽·발 표식, 이전 실패를 재구성할 경우 문제 재현 라벨; 없는 최초 실행 녹화 주장 금지'
plan.update(currentState='game deployed; seven OSS tools executed; SSD actual setup blocked and disclosed; additive audio prepared',website='https://yamyam-cartographers-room.eazuooz.chatgpt.site',unresolved=['Sprite-Sheet-Diffusion inference not completed: official PoseGuider missing; compatibility CLIP checkpoint URL404'],scriptModelReadthrough=True,scriptHumanListening=False)
adds=[s for s in plan['scenes'] if s['id'].startswith('R')]
(H/'revision-plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2),'utf8')
(H/'narration-additions.ko-en.json').write_text(json.dumps({'scenes':adds},ensure_ascii=False,indent=2),'utf8')
(H/'full-narration.ko.txt').write_text('\n\n'.join(s['ko'] for s in plan['scenes']),'utf8')
(H/'added.ko.json').write_text(json.dumps({'scenes':[{'id':s['id'],'title':s['title'],'lines':[s['ko']]} for s in adds]},ensure_ascii=False,indent=2),'utf8')
original=json.loads((P/'project.json').read_text('utf8'))
tts=original['tts'].copy();tts.update(outputDir=(P/'production/local/room-v2/voice').relative_to(R).as_posix(),filenameStem='room-additions')
manifest={'slug':P.name,'paths':{'script':(H/'added.ko.json').relative_to(R).as_posix()},'editing':{'narrationPlacement':'continuous-across-example-and-explanation'},'tts':tts}
(H/'tts-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),'utf8')
print('Frozen',len(adds),'new passages; original30 unchanged.')
